function card(r, i, top){
  const el = document.createElement('div');
  el.className = 'card';
  el.style.animationDelay = Math.min(i * 24, 260) + 'ms';

  const isFile = r.kind === 'file';       // 「我的文件」：读者自己放进去的，没有链接，看全文就是它本身
  const titleHtml = isFile ? esc(r.title)
    : `<a href="${esc(r.link)}" target="_blank" rel="noopener">${esc(r.title)}</a>`;

  const tags = [];
  if (r.date) tags.push(`<span>${r.date}</span>`);
  if (r.kind === 'comic') tags.push(`<span class="tag comic">漫画</span>`);
  if (isFile) tags.push(`<span class="tag">我的文件</span>`);
  if (r.read_num != null) tags.push(`<span class="tag">${r.read_num} 阅读</span>`);
  if (r.hit_count > 1) tags.push(`<span class="tag">文中 ${r.hit_count} 段相关</span>`);
  const lvl = r.score >= 0.60 ? ' strong' : r.score >= 0.30 ? '' : ' weak';
  tags.push(`<span class="tag score${lvl}" title="语义 ${(r.vec_score*100).toFixed(0)} / 字面 ${(r.lex_score*100).toFixed(0)}">匹配 ${r.rel}%</span>`);

  // 漫画常常没有正文，摘要就是标题本身，显示出来等于重复一遍。有图就不摆这句废话。
  const 去掉重复标题 = (s) => {
    const a = s.text.replace(/<[^>]+>/g, '').replace(/\s/g, '');
    const b = (r.title || '').replace(/\s/g, '');
    return !(a && b && (a === b || (a.length < b.length + 6 && b.includes(a.slice(0, 12)))));
  };
  const snips = r.snippets.filter(s => !r.thumbs || 去掉重复标题(s)).map(s =>
    `<p class="snip">${s.heading ? `<span class="h">${esc(s.heading)}</span>` : ''}${highlight(s.text)}</p>`
  ).join('');

  // 漫画有图就铺一行缩略图，点开原文
  const thumbs = r.thumbs
    ? `<div class="thumbs">` + Array.from({length: r.thumbs}, (_, n) =>
        `<a href="${esc(r.link)}" target="_blank" rel="noopener">` +
        `<img loading="lazy" alt="" src="/api/thumb?id=${encodeURIComponent(r.id)}&n=${n}"></a>`
      ).join('') + `</div>`
    : '';

  el.innerHTML = `
    <h2>${titleHtml}</h2>
    <div class="tags">${tags.join('')}</div>
    ${thumbs}
    ${snips}
    <div class="actions"></div>
    <div class="fulltext" hidden></div>`;

  const actions = el.querySelector('.actions');
  if (isFile) { actions.appendChild(fullBtn(r, el)); return el; }
  actions.appendChild(button('复制链接', () => r.link, true));
  actions.appendChild(button('复制标题 + 链接', () => `《${r.title}》\n${r.link}`));
  actions.appendChild(button('复制 Markdown 链接', () => `[《${r.title}》](${r.link})`));
  const open = document.createElement('a');
  open.className = 'btn'; open.href = r.link; open.target = '_blank'; open.rel = 'noopener';
  open.textContent = '打开原文';
  actions.appendChild(open);
  if (r.has_text) actions.appendChild(fullBtn(r, el));
  return el;
}

function button(label, getText, primary){
  const b = document.createElement('button');
  b.className = 'btn' + (primary ? ' primary' : '');
  b.textContent = label;
  b.onclick = async () => {
    const text = getText();
    try{
      await navigator.clipboard.writeText(text);
    }catch{
      const ta = document.createElement('textarea');
      ta.value = text; document.body.appendChild(ta); ta.select();
      document.execCommand('copy'); ta.remove();
    }
    const old = b.textContent;
    b.textContent = '已复制 ✓'; b.classList.add('done');
    setTimeout(() => { b.textContent = old; b.classList.remove('done'); }, 1400);
    toast(text.length > 46 ? text.slice(0, 46).replace(/\n/g, ' ') + '…' : text.replace(/\n/g, ' '));
  };
  return b;
}

function fullBtn(r, card){
  const box = card.querySelector('.fulltext');
  const b = document.createElement('button');
  b.className = 'btn'; b.textContent = '展开全文';
  b.onclick = async () => {
    if (!box.hidden){ box.hidden = true; b.textContent = '展开全文'; return; }
    if (!box.dataset.loaded){
      b.textContent = '加载中…';
      const d = await (await fetch('/api/doc?id=' + encodeURIComponent(r.id))).json();
      box.innerHTML = highlight(d.text || '（本地没存这篇的正文，点上面的「打开原文」看）', 40)
        .replace(/^#{2,4}\s+(.+)$/gm, '<b class="ft-h">$1</b>')   // 小标题别露出井号
        .replace(/^\s*-{3,}\s*$/gm, '');

